/* ===== QUICK GUIDE — where to change things (search for the words in CAPITALS) =====
 BUSINESS NAME / ADDRESS ... index.html (title + login) and here: search  ANSHA INAM PLASTIC INDUSTRY  and  Rahimabad
 MENU PAGES (add / rename / remove) ... search  const NAV
 EXPENSE CATEGORIES ... search  V.expenses  (the list called C)
 EMOJI SHOWN WHEN A PRODUCT HAS NO PICTURE ... search  const ICON
 PRODUCT PICTURES ... in the app: Settings → Product pictures (no code needed)
 CARDS PER ROW ... in the app: Settings → Cards per row, or css/style.css → .pgrid
 COLOURS / GLOSS / DARK + LIGHT ... css/style.css → :root  (gold = --g1 and --g2)
 WHO HANDLED A SALE (the 2 names) ... search  const byf  (also the check in supabase/schema.sql: handled_by)
 USERS / PASSWORDS ... Supabase → Authentication → Users;  allowed users: table allowed_users
 Never put your sb_secret key in any file. js/config.js only holds the public key. */
const sb=supabase.createClient(CFG.url,CFG.key);
let lang=localStorage.lang||'en',post=null,range,ME='',lastLedger=null,lastCash=[],lastParties=null;
const $=s=>document.querySelector(s);
const r2=n=>Math.round((+n+Number.EPSILON)*100)/100;
const sum=(a,f=x=>x)=>r2(a.reduce((s,x)=>s+ +f(x),0));
const fmt=n=>(+n||0).toLocaleString('en-PK',{maximumFractionDigits:2});
const iso=d=>new Date(d.getTime()-d.getTimezoneOffset()*6e4).toISOString().slice(0,10);
const today=()=>iso(new Date());
const L=(e,u)=>lang==='ur'?u:e;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pad=(p,id)=>p+String(id).padStart(6,'0');
const toast=m=>{const t=$('#toast');t.textContent=m;t.className='show';setTimeout(()=>t.className='',3500)};
function monthRange(){const n=new Date();return{from:iso(new Date(n.getFullYear(),n.getMonth(),1)),to:today()}}
range=monthRange();
const VT=['sales','purchases','payments','expenses','loans','loan_payments','loan_status'];
async function all(t,full){let o=[],i=0;for(;;){let q=sb.from(t).select('*');if(!full&&VT.includes(t))q=q.eq('voided',false);const{data,error}=await q.order('id').range(i,i+999);if(error)throw error;o=o.concat(data);if(data.length<1000)return o;i+=1000}}
async function rpc(n,a){const{data,error}=await sb.rpc(n,a);if(error){toast('⚠ '+error.message);throw error}return data}
async function ins(t,row){const{error}=await sb.from(t).insert(row);if(error){toast('⚠ '+error.message);throw error}}
const tbl=(h,rows)=>`<div class=tw><table><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan=${h.length} class=muted>${L('No records','کوئی ریکارڈ نہیں')}</td></tr>`}</tbody></table></div>`;
const tr=(c,a='')=>`<tr ${a}>${c.map(x=>`<td>${x}</td>`).join('')}</tr>`;
const fld=(n,l,t='text',v='',x='')=>`<label>${l}<input name=${n} type=${t} value="${esc(v)}" ${x}></label>`;
const sel=(n,l,o,v='')=>`<label>${l}<select name=${n}>${o.map(([a,b,p])=>`<option value="${a}" ${a==v?'selected':''} ${p!=null?`data-p="${p}"`:''}>${esc(b)}</option>`).join('')}</select></label>`;
const METHOD=[['cash','Cash · نقد'],['bank','Bank · بینک']];
const byf=()=>sel('by','By · کس نے',[['Inamullah','Inamullah'],['Aizaz Khan','Aizaz Khan']],localStorage.by||'Inamullah');
const tip=(e,u)=>`<div class=tip><span>💡</span><span>${L(e,u)}</span></div>`;
const stats=c=>`<div class=grid>${c.map(([l,v,k,u])=>`<div class=stat><small>${l}</small><b class="${k||''}">${u==null?'Rs ':u}${fmt(v)}</b></div>`).join('')}</div>`;
const wa=(m,t)=>{m=String(m||'').replace(/\D/g,'');if(m.startsWith('0'))m='92'+m.slice(1);return`https://wa.me/${m}?text=${encodeURIComponent(t)}`};
function chart(id,type,labels,sets){const c=$('#'+id),cs=getComputedStyle(document.documentElement),tx=cs.getPropertyValue('--mut').trim(),gr=cs.getPropertyValue('--line').trim();if(c)new Chart(c,{type,data:{labels,datasets:sets.map((s,i)=>({...s,borderColor:['#d4a72c','#7fb7d9','#e0675b'][i],backgroundColor:['#d4a72caa','#7fb7d9aa','#e0675baa'][i],tension:.3}))},options:{responsive:true,color:tx,scales:{x:{ticks:{color:tx},grid:{color:gr}},y:{ticks:{color:tx},grid:{color:gr}}},plugins:{legend:{labels:{color:tx}}}}})}
// HINT: each page = [route, English name, Urdu name, icon]. Add / rename / reorder here; the top bar updates by itself.
const NAV=[['dash','Dashboard','ڈیش بورڈ','📊'],['products','Products & Stock','مصنوعات و اسٹاک','📦'],['sales','Sales','فروخت','🧾'],['purchases','Purchases','خریداری','🛒'],['customers','Customers','گاہک','👥'],['suppliers','Suppliers','سپلائرز','🏭'],['given','Loan Given','قرض دیا','💸'],['taken','Loan Taken','قرض لیا','🏦'],['expenses','Expenses','اخراجات','🧮'],['cash','Cash Flow','کیش فلو','💰'],['reports','Reports & Profit','رپورٹس و منافع','📈'],['log','Backup & Log','بیک اپ و لاگ','🛡️'],['settings','Settings','سیٹنگز','⚙️']];
function drawNav(k){document.documentElement.dir=lang==='ur'?'rtl':'ltr';const act={product:'products',ledger:'customers'}[k]||k;$('#navLinks').innerHTML=NAV.map(([id,e,u,i])=>`<a href="#/${id}" class="${id===act?'on':''}">${i} ${L(e,u)}</a>`).join('');$('#lEn').classList.toggle('on',lang==='en');$('#lUr').classList.toggle('on',lang==='ur');moveInd()}
function moveInd(){const a=$('#navLinks a.on'),i=$('#navInd');if(!a){i.style.width='0px';return}requestAnimationFrame(()=>{i.style.width=a.offsetWidth+'px';i.style.transform=`translateX(${a.offsetLeft}px)`;a.scrollIntoView&&a.scrollIntoView({inline:'center',block:'nearest',behavior:'smooth'})})}
addEventListener('resize',moveInd);document.fonts&&document.fonts.ready.then(moveInd);
const V={};const H={};
// ---------- Dashboard
V.dash=async()=>{
 const[S,P,Pay,E,LP,LN,B,PR]=await Promise.all(['sales','purchases','payments','expenses','loan_payments','loans','party_balance','products'].map(all));
 const d=today(),ts=S.filter(x=>x.d===d),kind={};LN.forEach(l=>kind[l.id]=l.kind);
 const gp=sum(ts,x=>x.qty*(x.unit_price-x.unit_cost)),ex=sum(E.filter(x=>x.d===d),x=>x.amount),net=r2(gp-ex),lp=k=>sum(LP.filter(x=>x.d===d&&kind[x.loan_id]===k),x=>x.amount);
 const days=[...Array(14)].map((_,i)=>iso(new Date(Date.now()-(13-i)*864e5)));
 const byP=PR.map(p=>S.filter(s=>s.product_id===p.id));
 post=()=>{chart('c1','line',days.map(x=>x.slice(5)),[{label:L('Daily sales','روزانہ فروخت'),data:days.map(x=>sum(S.filter(s=>s.d===x),s=>s.total))}]);chart('c2','bar',PR.map(p=>p.name_en),[{label:L('Sales by product','مصنوعات کی فروخت'),data:byP.map(a=>sum(a,s=>s.total))}])};
 return`<h2>${L('Dashboard','ڈیش بورڈ')} · ${d}</h2>${tip('Tap any product to see all its details. Change pictures or cards-per-row in Settings.','کسی بھی پروڈکٹ پر ٹیپ کریں۔ تصاویر اور کارڈز کی تعداد سیٹنگز میں بدلیں۔')}`+stats([[L('Today sales','آج کی فروخت'),sum(ts,x=>x.total)],[L('Today purchases','آج کی خریداری'),sum(P.filter(x=>x.d===d),x=>x.total)],[L('Collected','آج کی وصولی'),sum(Pay.filter(x=>x.d===d&&x.dir==='in'),x=>x.amount)],[L('Paid out','آج کی ادائیگی'),sum(Pay.filter(x=>x.d===d&&x.dir==='out'),x=>x.amount)],[L('Expenses','آج کے اخراجات'),ex],[net>=0?L('Today profit','آج کا منافع'):L('Today loss','آج کا نقصان'),Math.abs(net),net>=0?'pos':'neg'],[L('Loan given today','آج دیا گیا قرض'),sum(LN.filter(x=>x.d===d&&x.kind==='given'),x=>x.amount)],[L('Loan recovered today','آج وصول قرض'),lp('given')],[L('Loan repaid today','آج واپس کیا قرض'),lp('taken')],[L('Customers owe','گاہکوں کا بقایا'),sum(B.filter(x=>x.kind==='customer'&&x.balance>0),x=>x.balance)],[L('We owe suppliers','سپلائرز کے بقایا'),sum(B.filter(x=>x.kind==='supplier'&&x.balance>0),x=>x.balance)],[L('Stock value','اسٹاک کی مالیت'),sum(PR,p=>p.stock*p.buy_price)]])
 +`<div class=pgrid>${PR.map(p=>pcard(p)).join('')}</div><div class=card style="margin-top:16px"><canvas id=c1></canvas></div><div class=card><canvas id=c2></canvas></div>`};
// HINT: emoji used on a card when the product has no picture (matches the first word of the product name).
const ICON={Magga:'🪣',Sabzi:'🥬',Katkay:'🥤',Basket:'🧺',Hangers:'👔',Chaba:'🍽️',Glass:'🥛'};
const pcard=p=>`<a class=pcard id=p${p.id} href="#/product/${p.id}"><div class=pimg style="${p.image_url?`background-image:url('${esc(p.image_url)}')`:''}">${p.image_url?'':ICON[p.name_en.split(' ')[0]]||'📦'}</div><div><b>${esc(lang==='ur'?p.name_ur||p.name_en:p.name_en)}</b><br><span class=muted>${L('Stock','اسٹاک')}: ${fmt(p.stock)}</span> ${p.stock<=p.min_stock?`<span class="badge low">${L('Low','کم')}</span>`:''}<br class=pm><span class="muted pm">${L('Cost','لاگت')} ${fmt(p.buy_price)} → ${L('Sell','فروخت')} ${fmt(p.sell_price)}</span></div></a>`;
// ---------- Products & stock
V.products=async a=>{const PR=await all('products');post=()=>a&&$('#p'+a)?.scrollIntoView({block:'center'});
 return`<h2>${L('Products & Stock','مصنوعات و اسٹاک')}</h2><p class=muted>${L('Cost price is the average of your purchases. To add or change pictures: Settings → Product pictures.','لاگت خریداری کی اوسط سے خودکار بنتی ہے۔')}</p><form class=card data-act=addprod><h3>＋ ${L('New product','نیا پروڈکٹ')}</h3><div class=form2>${fld('name_en','Name (English)','text','','required')}${fld('name_ur','نام (اردو)')}${fld('sell','Selling price · فروخت قیمت','number',0,'min=0 step=any')}${fld('min','Low-stock alert · کم اسٹاک حد','number',100,'min=0')}<label>${L('Picture (optional)','تصویر (اختیاری)')}<input type=file name=photo accept="image/*"></label></div><button class=btn>＋ ${L('Add product','پروڈکٹ شامل کریں')}</button></form><div class="pgrid wide">${PR.map(p=>`<div class=card style="padding:0;${a==p.id?'outline:2px solid var(--pri)':''}">${pcard(p)}<div style="padding:0 10px 10px"><button class="btn sm alt" data-act=editp data-id=${p.id}>✏️ ${L('Edit','ترمیم')}</button> <button class="btn sm alt" data-act=adj data-id=${p.id}>± ${L('Stock adjust','اسٹاک ایڈجسٹ')}</button></div></div>`).join('')}</div>`};
V.product=async(id,mode)=>{
 const[pr,S,P,A,B]=await Promise.all([sb.from('products').select('*').eq('id',id).single(),all('sales'),all('purchases'),all('stock_adjustments'),all('party_balance')]);
 const p=pr.data;if(!p)throw Error('Product not found');
 const nm=Object.fromEntries(B.map(x=>[x.id,x.name])),n=new Date(),start=mode==='today'?today():mode==='month'?iso(new Date(n.getFullYear(),n.getMonth(),1)):'0000-00-00';
 const sa=S.filter(x=>x.product_id==id),pu=P.filter(x=>x.product_id==id),ad=A.filter(x=>x.product_id==id).reverse().slice(0,10),s=sa.filter(x=>x.d>=start),u=pu.filter(x=>x.d>=start);
 const rev=sum(s,x=>x.total),cogs=sum(s,x=>x.qty*x.unit_cost),profit=r2(rev-cogs),low=p.stock<=p.min_stock,days=[...Array(30)].map((_,i)=>iso(new Date(Date.now()-(29-i)*864e5)));
 post=()=>chart('c1','line',days.map(x=>x.slice(5)),[{label:L('Revenue (30 days)','آمدنی (30 دن)'),data:days.map(d=>sum(sa.filter(x=>x.d===d),x=>x.total))},{label:L('Profit','منافع'),data:days.map(d=>sum(sa.filter(x=>x.d===d),x=>x.qty*(x.unit_price-x.unit_cost)))}]);
 const top=Object.values(s.reduce((o,x)=>{const t=o[x.party_id]=o[x.party_id]||{n:nm[x.party_id],q:0,r:0,g:0};t.q+=+x.qty;t.r+=+x.total;t.g+=x.qty*(x.unit_price-x.unit_cost);return o},{})).sort((a,b)=>b.r-a.r).slice(0,5);
 const tab=(m,l)=>`<a class="btn sm ${(mode||'')===m?'':'alt'}" style="text-decoration:none;display:inline-block" href="#/product/${id}${m?'/'+m:''}">${l}</a>`;
 return`<p class=muted><a href="#/products">← ${L('Products','مصنوعات')}</a></p><div class="card hero"><div class=himg style="${p.image_url?`background-image:url('${esc(p.image_url)}')`:''}">${p.image_url?'':ICON[p.name_en.split(' ')[0]]||'📦'}</div><div><h2>${esc(p.name_en)}</h2><p class=muted>${esc(p.name_ur||'')}</p><span class="badge ${low?'low':'Paid'}">${low?L('Low stock','کم اسٹاک'):L('In stock','اسٹاک موجود')}</span><br><button class="btn sm alt" style="margin-top:10px" data-act=editp data-id=${p.id}>✏️ ${L('Edit price / alert','قیمت / الرٹ')}</button> <button class="btn sm alt" data-act=adj data-id=${p.id}>± ${L('Adjust stock','اسٹاک ایڈجسٹ')}</button> <label class="btn sm alt">📷 ${L('Picture','تصویر')}<input class=file type=file accept="image/*" data-pid=${p.id}></label></div></div>`
 +stats([[L('Stock now (pcs)','موجودہ اسٹاک'),p.stock,low?'neg':'pos','' ],[L('Low-stock alert at','کم اسٹاک حد'),p.min_stock,'',''],[L('Cost / piece (avg)','فی عدد لاگت'),p.buy_price],[L('Selling price / piece','فی عدد فروخت'),p.sell_price],[L('Profit / piece','فی عدد منافع'),r2(p.sell_price-p.buy_price),p.sell_price>=p.buy_price?'pos':'neg'],[L('Stock value','اسٹاک کی مالیت'),r2(p.stock*p.buy_price)]])
 +`<p>${tab('today',L('Today','آج'))} ${tab('month',L('This month','اس مہینے'))} ${tab('',L('All time','تمام'))}</p>`
 +stats([[L('Sold (pcs)','فروخت شدہ'),sum(s,x=>x.qty),'',''],[L('Sales amount','فروخت کی رقم'),rev],[L('Cost of sold','فروخت شدہ کی لاگت'),cogs],[profit>=0?L('Profit','منافع'):L('Loss','نقصان'),Math.abs(profit),profit>=0?'pos':'neg'],[L('Purchased (pcs)','خریدا گیا'),sum(u,x=>x.qty),'',''],[L('Spent on purchases','خریداری پر خرچ'),sum(u,x=>x.total)]])
 +`<div class=card><canvas id=c1></canvas></div><h3>${L('Top customers','بہترین گاہک')}</h3>`+tbl([L('Customer','گاہک'),L('Qty','مقدار'),L('Sales','فروخت'),L('Profit','منافع')],top.map(x=>tr([esc(x.n),fmt(x.q),fmt(x.r),fmt(r2(x.g))])))
 +`<h3>${L('Recent sales','حالیہ فروخت')}</h3>`+tbl(['Date','Customer','Qty','Price','Total','Profit'],s.slice().reverse().slice(0,15).map(x=>tr([x.d,esc(nm[x.party_id]),fmt(x.qty),fmt(x.unit_price),fmt(x.total),`<b class=pos>${fmt(r2(x.qty*(x.unit_price-x.unit_cost)))}</b>`])))
 +`<h3>${L('Recent purchases','حالیہ خریداری')}</h3>`+tbl(['Date','Supplier','Qty','Price','Total'],u.slice().reverse().slice(0,15).map(x=>tr([x.d,esc(nm[x.party_id]),fmt(x.qty),fmt(x.unit_price),fmt(x.total)])))
 +`<h3>${L('Stock adjustments','اسٹاک ایڈجسٹمنٹ')}</h3>`+tbl(['Date','Change','Reason'],ad.map(x=>tr([x.d,`<b class="${x.delta>0?'pos':'neg'}">${x.delta>0?'+':''}${fmt(x.delta)}</b>`,esc(x.reason)])))};
// ---------- Printable reports (Save as PDF) — shows who generated it and when
const stamp=()=>{const n=new Date();return n.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})+', '+n.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',hour12:true})};
const plain=s=>String(s??'').replace(/<[^>]*>/g,'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#39;/g,"'").replace(/&quot;/g,'"');
const fname=t=>('Ansha-Inam_'+t+'_'+iso(new Date())+'_'+new Date().toTimeString().slice(0,5).replace(':','')+'_'+ME.split(' (')[0]).replace(/[^\w\-]+/g,'_');
function report(o){const when=stamp(),ref='RPT-'+Date.now().toString(36).toUpperCase(),rc=(r,i)=>r.includes(i)?' class=r':'';
 const tb=(h,b,r=[])=>`<table><thead><tr>${h.map((x,i)=>`<th${rc(r,i)}>${esc(x)}</th>`).join('')}</tr></thead><tbody>${b.map(w=>`<tr>${w.map((c,i)=>`<td${rc(r,i)}>${esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
 $('#modal').hidden=false;$('#modal').scrollTop=0;
 $('#modal').innerHTML=`<div class=rwrap><div class="rbar no-print"><button class=btn data-act=doprint data-n="${esc(o.file)}">⬇ ${L('Save as PDF / Print','PDF محفوظ کریں / پرنٹ')}</button><button class="btn alt" data-act=close>✖ ${L('Close','بند کریں')}</button><span class=muted>${L('In the print window choose “Save as PDF”.','پرنٹ ونڈو میں “Save as PDF” منتخب کریں۔')}</span></div><div class=paper><div class=ph><img class=pl src="${LOGO}" alt=""><div><h1>ANSHA INAM PLASTIC INDUSTRY</h1><p>Rahimabad, Mingora, Swat · Pakistan</p></div></div><div class=pb><h2>${esc(o.title)}</h2><p class=psub>${esc(o.sub||'')}</p><div class=pinfo><span><b>Generated by:</b> ${esc(ME)}</span><span><b>Date &amp; time:</b> ${when}</span><span><b>Ref:</b> ${ref}</span></div>`
 +(o.summary?.length?`<h3>Summary</h3><table class=sum><tbody>${o.summary.map(([k,v])=>`<tr><td>${esc(k)}</td><td class=r>${esc(v)}</td></tr>`).join('')}</tbody></table>`:'')
 +(o.sections||[]).filter(s=>s.body.length).map(s=>`<h3>${esc(s.h)}</h3>${tb(s.head,s.body,s.right)}`).join('')
 +`</div><div class=pfoot><span>Generated by ${esc(ME)} on ${when}</span><span>Private &amp; confidential</span></div></div></div>`}
H.doprint=d=>{const old=document.title;document.title=d.n;addEventListener('afterprint',()=>{document.title=old},{once:true});print()};
async function repPdf(from,to,title,extra){const r=await data(from,to),f=x=>fmt(x);
 report({title,sub:`Period: ${from}${from===to?'':' to '+to}`,file:fname(title.replace(/\W+/g,'-')),summary:[...(extra||[]),...Object.entries(r.sum1).map(([k,v])=>[k,'Rs '+fmt(v)])],sections:[
 {h:'Daily summary',head:['Date','Sales','Purchases','Received','Paid out','Expenses','Gross profit','Net profit'],body:r.daily.map(x=>Object.values(x).map((v,i)=>i?f(v):v)),right:[1,2,3,4,5,6,7]},
 {h:'Profit by product',head:['Product','Qty sold','Revenue','Cost','Profit','Stock now'],body:r.prod.map(x=>Object.values(x).map((v,i)=>i?f(v):v)),right:[1,2,3,4,5]},
 {h:'Sales',head:['No.','Date','Customer','Product','Qty','Price','Total','By'],body:r.sheets.Sales.map(x=>[x.No,x.Date,x.Customer,x.Product,f(x.Qty),f(x.Price),f(x.Total),x.By]),right:[4,5,6]},
 {h:'Purchases',head:['No.','Date','Supplier','Product','Qty','Price','Total','By'],body:r.sheets.Purchases.map(x=>[x.No,x.Date,x.Supplier,x.Product,f(x.Qty),f(x.Price),f(x.Total),x.By]),right:[4,5,6]},
 {h:'Payments',head:['Date','Party','Type','Amount','Method','By'],body:r.sheets.Payments.map(x=>[x.Date,x.Party,x.Direction==='in'?'Received':'Paid',f(x.Amount),x.Method,x.By]),right:[3]},
 {h:'Expenses',head:['Date','Category','Amount','Method','Note'],body:r.sheets.Expenses.map(x=>[x.Date,x.Category,f(x.Amount),x.Method,x.Note||'']),right:[2]}]})}
H.reppdf=()=>repPdf(range.from,range.to,'Sales & Profit Report');
H.closingpdf=()=>repPdf(today(),today(),'Daily Cash Closing',lastCash);
H.stmt=()=>{const g=lastLedger;if(!g)return;const{p,c,owes,given,taken,PL,open,start}=g,per=start>'0000'?`${start} to ${today()}`:'All records';
 report({title:`${c?'Customer':'Supplier'} Account Statement`,sub:`${p.name}${p.mobile?' · '+p.mobile:''} — ${per}`,file:fname('Statement_'+p.name),summary:[[owes>0?'He owes you (goods + loans)':owes<0?'You owe him (goods + loans)':'Account status',owes?'Rs '+fmt(Math.abs(owes)):'Clear'],[c?'Goods balance he owes (advance in brackets)':'Goods balance you owe (advance in brackets)',p.balance<0?'('+fmt(-p.balance)+')':fmt(p.balance)],['Cash loan given to him (left)','Rs '+fmt(given)],['Cash loan taken from him (left)','Rs '+fmt(taken)]],sections:[{h:'Entries',head:['Date','Details','Debit','Credit','Balance'],body:[...(start>'0000'?[['','Previous balance','','',fmt(open)]]:[]),...PL],right:[2,3,4]}]})};
H.stmtx=()=>{const g=lastLedger;if(!g)return;const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([['Account statement',g.p.name],['Generated by',ME],['Generated at',stamp()],[],['Date','Details','Debit','Credit','Balance'],...g.PL]),'Statement');XLSX.writeFile(wb,fname('Statement_'+g.p.name)+'.xlsx')};
H.partypdf=()=>{const g=lastParties;if(!g)return;const c=g.k==='customer';report({title:`${c?'Customers':'Suppliers'} — Balances`,sub:`As of ${stamp()}`,file:fname(c?'Customers':'Suppliers'),summary:[[c?'Total customers owe you':'Total you owe suppliers','Rs '+fmt(sum(g.B.filter(x=>x.balance>0),x=>x.balance))],[c?'Advances you hold':'Advances you paid','Rs '+fmt(-sum(g.B.filter(x=>x.balance<0),x=>x.balance))]],sections:[{h:'List',head:['Name','Mobile',c?'Due / (Advance)':'We owe / (Advance)'],body:g.B.map(x=>[x.name,x.mobile||'',x.balance<0?'('+fmt(-x.balance)+')':fmt(x.balance)]),right:[2]}]})};
H.addprod=async(d,f)=>{const{data,error}=await sb.from('products').insert({name_en:d.name_en,name_ur:d.name_ur||null,sell_price:+d.sell||0,min_stock:+d.min||0}).select('id').single();if(error){toast('⚠ '+error.message);throw error}const file=f.elements.photo&&f.elements.photo.files[0];if(file){try{await setPhoto(data.id,file)}catch(_){}}toast('✔');route()};
// ---------- Product pictures
// HINT: a picture is shrunk in the browser (max 640 px, JPEG) and saved in Supabase Storage bucket "product-images"; its link goes in products.image_url.
async function shrink(file,max=640){const bmp=await createImageBitmap(file),k=Math.min(1,max/Math.max(bmp.width,bmp.height)),c=document.createElement('canvas');c.width=Math.round(bmp.width*k);c.height=Math.round(bmp.height*k);c.getContext('2d').drawImage(bmp,0,0,c.width,c.height);return new Promise(r=>c.toBlob(r,'image/jpeg',.85))}
async function setPhoto(pid,file){const blob=await shrink(file),path=`p${pid}.jpg`,st=sb.storage.from('product-images');
 const{error}=await st.upload(path,blob,{upsert:true,contentType:'image/jpeg',cacheControl:'3600'});if(error){toast('⚠ '+error.message);throw error}
 const url=st.getPublicUrl(path).data.publicUrl+'?v='+Date.now(),{error:e2}=await sb.from('products').update({image_url:url}).eq('id',pid);if(e2){toast('⚠ '+e2.message);throw e2}}
document.addEventListener('change',async e=>{const i=e.target.closest('input[data-pid]');if(!i||!i.files[0])return;toast(L('Uploading picture…','تصویر اپ لوڈ ہو رہی ہے…'));try{await setPhoto(+i.dataset.pid,i.files[0]);toast('✔ '+L('Picture saved','تصویر محفوظ ہو گئی'));route()}catch(_){}});
H.rmphoto=async d=>{if(!confirm(L('Remove this picture?','یہ تصویر ہٹائیں؟')))return;const{error}=await sb.from('products').update({image_url:null}).eq('id',d.id);if(error)return toast('⚠ '+error.message);sb.storage.from('product-images').remove([`p${d.id}.jpg`]);route()};
// HINT: cards per row on the dashboard (Settings → Cards per row). 'auto' = 3 on phone, 4 on tablet, 5 on desktop (see .pgrid in css/style.css).
function applyCols(){const n=localStorage.cols,r=document.documentElement.style;n&&n!=='auto'?r.setProperty('--cols',n):r.removeProperty('--cols')}
H.cols=d=>{localStorage.cols=d.n;applyCols();route()};
const picCards=(PR,cn)=>`<div class=card><h3>📷 ${L('Product pictures','مصنوعات کی تصاویر')}</h3>${tip('Tap “Add picture” to take a photo or choose one from your gallery. New products show up here automatically. Square photos look best.','“تصویر لگائیں” دبا کر فوٹو کھینچیں یا گیلری سے چنیں۔ نئے پروڈکٹ یہاں خود آ جاتے ہیں۔ چوکور تصویر بہتر لگتی ہے۔')}${PR.map(p=>`<div class=prow><div class=thumb style="${p.image_url?`background-image:url('${esc(p.image_url)}')`:''}">${p.image_url?'':ICON[p.name_en.split(' ')[0]]||'📦'}</div><div class=nm><b>${esc(p.name_en)}</b><br><span class=muted>${esc(p.name_ur||'')}</span></div><label class="btn sm alt">📷 ${p.image_url?L('Change','تبدیل'):L('Add picture','تصویر لگائیں')}<input class=file type=file accept="image/*" data-pid=${p.id}></label>${p.image_url?` <button class="btn sm alt" data-act=rmphoto data-id=${p.id} title="Remove">🗑️</button>`:''}</div>`).join('')}</div><div class=card><h3>▦ ${L('Cards per row on the dashboard','ڈیش بورڈ پر ایک قطار میں کارڈز')}</h3><p>${['auto',3,4,5,6].map(n=>`<button class="btn sm ${String(n)===cn?'':'alt'}" data-act=cols data-n=${n}>${n==='auto'?L('Auto','خودکار'):n}</button>`).join(' ')}</p></div>`;
H.editp=async d=>{const p=(await sb.from('products').select('*').eq('id',d.id).single()).data;const sp=prompt('Selling price / فروخت قیمت',p.sell_price);if(sp===null)return;const ms=prompt('Low-stock alert level / کم اسٹاک حد',p.min_stock);if(ms===null)return;const im=prompt('Image path or URL (e.g. img/lota.jpg)',p.image_url||'');if(im===null)return;const{error}=await sb.from('products').update({sell_price:+sp,min_stock:+ms,image_url:im||null}).eq('id',d.id);error?toast('⚠ '+error.message):route()};
H.adj=async d=>{const q=prompt('Stock change (+ or −) / اسٹاک میں تبدیلی');if(!q||isNaN(+q))return;const r=prompt('Reason / وجہ (e.g. damaged, count correction)');if(!r)return toast('Reason required');await rpc('adjust_stock',{p_product:+d.id,p_delta:+q,p_reason:r});route()};
// ---------- Sales & purchases
async function trade(k){const isS=k==='sales',[PR,B,R]=await Promise.all([all('products'),all('party_balance'),all(k)]);
 const pt=B.filter(x=>x.kind===(isS?'customer':'supplier')&&!x.archived),pn=Object.fromEntries(B.map(x=>[x.id,x.name])),pr=Object.fromEntries(PR.map(x=>[x.id,x.name_en]));
 const first=PR[0];post=()=>{const f=document.querySelector('form[data-act=trade]');f&&preview(f)};
 return`<h2>${isS?L('Sales','فروخت'):L('Purchases','خریداری')}</h2>${tip(isS?'Pick the customer: a red line shows what he already owes you (or his advance). Use “Full payment” or “Credit” to fill Paid quickly.':'Pick the supplier: a red line shows what you already owe him. Cost price updates automatically from purchases.',isS?'گاہک چنیں: سرخ لائن میں اس کا پچھلا حساب نظر آئے گا۔ “مکمل ادائیگی” یا “ادھار” دبا کر رقم بھریں۔':'سپلائر چنیں: سرخ لائن میں آپ کا پچھلا قرض نظر آئے گا۔ لاگت خریداری سے خود بدلتی ہے۔')}<form class=card data-act=trade data-kind=${k}><div class=form2>${sel('party',isS?'Customer · گاہک':'Supplier · سپلائر',pt.map(x=>[x.id,x.name,x.balance]))}${sel('product','Product · پروڈکٹ',PR.map(x=>[x.id,x.name_en+' ('+fmt(x.stock)+')',isS?x.sell_price:x.buy_price]))}${fld('qty','Quantity · مقدار','number','','min=1 step=any required')}${fld('price','Price/piece · فی عدد قیمت','number',first?(isS?first.sell_price:first.buy_price):'','min=0 step=any required')}${fld('paid','Paid now · ادا شدہ','number',0,'min=0 step=any')}${sel('method','Method · طریقہ',METHOD)}${byf()}${fld('date','Date · تاریخ','date',today(),'required')}</div><div class=pv style="margin-top:8px"></div><button class=btn type=submit>💾 ${L('Save','محفوظ کریں')}</button> <button type=button class="btn alt" data-act=setpaid data-v=full>${L('Full payment','مکمل ادائیگی')}</button> <button type=button class="btn alt" data-act=setpaid data-v=credit>${L('Credit','ادھار')}</button> <button type=button class="btn alt" data-act=newparty data-kind=${isS?'customer':'supplier'}>＋ ${isS?L('New customer','نیا گاہک'):L('New supplier','نیا سپلائر')}</button></form>`
 +tbl(['No.','Date','Party','Product','Qty','Price','Total','By',''],R.slice().reverse().slice(0,200).map(x=>tr([pad(isS?'S-':'P-',x.id),x.d,esc(pn[x.party_id]),esc(pr[x.product_id]),fmt(x.qty),fmt(x.unit_price),fmt(x.total),esc(x.handled_by||''),`<button class="btn sm alt" data-act=inv data-k=${k} data-id=${x.id}>🧾</button> <button class="btn sm alt" data-act=del data-t=${k} data-id=${x.id} title="Delete">✖</button>`])))}
V.sales=()=>trade('sales');V.purchases=()=>trade('purchases');
H.trade=async(d,f)=>{const k=f.dataset.kind;if(!d.party)return toast(L('Add a party first','پہلے پارٹی شامل کریں'));const id=await rpc(k==='sales'?'create_sale':'create_purchase',{p_party:+d.party,p_product:+d.product,p_qty:+d.qty,p_price:+d.price,p_paid:+d.paid||0,p_method:d.method,p_date:d.date,p_by:d.by});localStorage.by=d.by;toast('✔ '+L('Saved','محفوظ ہو گیا'));await route();inv({k,id})};
H.setpaid=(d,b)=>{const x=b.closest('form').elements;x.paid.value=d.v==='full'?r2(x.qty.value*x.price.value):0;x.paid.dispatchEvent(new Event('input',{bubbles:true}))};
H.newparty=async d=>{const n=prompt('Name / نام');if(!n)return;const m=prompt('Mobile / موبائل نمبر')||null;await ins('parties',{kind:d.kind,name:n,mobile:m});route()};
function preview(f){const x=f.elements,isS=f.dataset.kind==='sales',t=r2(x.qty.value*x.price.value),p=+x.paid.value||0,rem=r2(t-p),b=+(x.party.selectedOptions[0]?.dataset.p||0);
 const prev=b>0?(isS?L('Previous balance: this customer owes you','پچھلا حساب: اس نے آپ کو دینا ہے'):L('Previous balance: you owe this supplier','پچھلا حساب: آپ نے اسے دینا ہے'))+' Rs '+fmt(b):b<0?(isS?L('Advance: you owe this customer','ایڈوانس: آپ نے اسے دینا ہے'):L('Advance: this supplier owes you','ایڈوانس: اس نے آپ کو دینا ہے'))+' Rs '+fmt(-b):'';
 f.querySelector('.pv').innerHTML=`<div class=grid style="margin:0 0 8px"><div class=stat><small>${L('Total bill','کل بل')}</small><b>Rs ${fmt(t)}</b></div><div class=stat><small>${L('Paid','ادا شدہ')}</small><b class=pos>Rs ${fmt(p)}</b></div><div class=stat><small>${L('Remaining','باقی')}</small><b class=neg>Rs ${fmt(rem)}</b></div></div>${prev?`<b class=neg>⚠ ${prev}</b><br>`:''}${b||rem?`<span class=muted>${L('Balance after this bill','اس بل کے بعد کل بقایا')}: Rs ${fmt((isS?b:b)+rem)}</span>`:''}`}
document.addEventListener('input',e=>{const f=e.target.closest('form[data-act=trade]');if(!f)return;if(e.target.name==='product'){const o=f.elements.product.selectedOptions[0];if(o?.dataset.p)f.elements.price.value=o.dataset.p}preview(f)});
// ---------- Invoice
async function inv({k,id}){const isS=k==='sales',pre=isS?'S-':'P-';
 const{data:s}=await sb.from(k).select('*,parties(name,mobile),products(name_en,name_ur)').eq('id',id).single();
 const paid=sum((await sb.from('payments').select('amount').eq('ref',pad(pre,id)).eq('voided',false)).data||[],x=>x.amount);
 const bal=(await sb.from('party_balance').select('balance').eq('id',s.party_id).single()).data.balance,due=r2(s.total-paid);
 const st=due<=0?'Paid':paid>0?'Partial':'Credit';
 const msg=`Ansha Inam Plastic Industry\n${isS?'Invoice':'Purchase'} ${pad(pre,id)} (${s.d})\n${s.products.name_en} × ${fmt(s.qty)} @ Rs ${fmt(s.unit_price)}\nTotal: Rs ${fmt(s.total)}\nPaid: Rs ${fmt(paid)}\nBalance: Rs ${fmt(due)} (${st})\nAccount balance: Rs ${fmt(bal)}`;
 $('#modal').hidden=false;$('#modal').innerHTML=`<div class="card inv"><img class=il src="${LOGO}" alt=""><h2>Ansha Inam Plastic Industry</h2><p class=muted style="text-align:center">Rahimabad, Mingora, Swat · ${isS?'Invoice / رسید':'Purchase Receipt / خریداری رسید'}</p><table><tr><td>No.</td><td><b>${pad(pre,id)}</b></td></tr><tr><td>Date</td><td>${s.d}</td></tr><tr><td>By</td><td>${esc(s.handled_by||'')}</td></tr><tr><td>${isS?'Customer':'Supplier'}</td><td>${esc(s.parties.name)}</td></tr><tr><td>Product</td><td>${esc(s.products.name_en)} · ${esc(s.products.name_ur||'')}</td></tr><tr><td>Quantity</td><td>${fmt(s.qty)}</td></tr><tr><td>Price/piece</td><td>Rs ${fmt(s.unit_price)}</td></tr><tr class=tot><td>Total</td><td>Rs ${fmt(s.total)}</td></tr><tr><td>Paid</td><td>Rs ${fmt(paid)}</td></tr><tr><td>Balance (this bill)</td><td>Rs ${fmt(due)}</td></tr><tr><td>Status</td><td><span class="badge ${st}">${st}</span></td></tr><tr><td>Total account balance</td><td>Rs ${fmt(bal)}</td></tr></table><p class=muted style="text-align:center;margin-top:12px">Printed by ${esc(ME)} · ${stamp()}</p><div class=no-print><button class=btn data-act=doprint data-n="${esc(fname('Invoice_'+pad(pre,id)+'_'+s.parties.name))}">🖨️ Print / PDF</button> <a class="btn alt" style="display:inline-block;text-decoration:none" target=_blank href="${wa(s.parties.mobile,msg)}">WhatsApp</a> <button class="btn alt" data-act=close>✖</button></div></div>`}
H.inv=d=>inv(d);H.close=()=>{$('#modal').hidden=true};
// ---------- Parties & ledger
const party=k=>async()=>{const B=(await all('party_balance')).filter(x=>x.kind===k&&!x.archived),c=k==='customer';lastParties={k,B};
 return`<h2>${c?L('Customers','گاہک'):L('Suppliers','سپلائرز')}</h2><form class=card data-act=addparty data-kind=${k}><div class=form2>${fld('name','Name · نام','text','','required')}${fld('mobile','Mobile · موبائل')}</div><button class=btn>＋ ${L('Add','شامل کریں')}</button></form><p><button class="btn sm alt" data-act=partypdf>⬇ ${L('List PDF','فہرست PDF')}</button></p>`+tbl([L('Name','نام'),L('Mobile','موبائل'),c?L('Due / (Advance)','بقایا / (ایڈوانس)'):L('We owe','ہم نے دینا'),''],B.map(x=>tr([`<a href="#/ledger/${x.id}"><b>${esc(x.name)}</b></a>`,esc(x.mobile),`<b class="${x.balance>0?'neg':'pos'}">${x.balance<0?'('+fmt(-x.balance)+')':fmt(x.balance)}</b>`,`<button class="btn sm alt" data-act=editparty data-id=${x.id}>✏️</button> <button class="btn sm alt" data-act=del data-t=parties data-id=${x.id}>🗑️</button>`])))};
V.customers=party('customer');V.suppliers=party('supplier');
H.del=d=>{$('#modal').hidden=false;$('#modal').innerHTML=`<form class=card data-act=delform data-t=${d.t} data-id=${d.id}><h3 class=neg>🗑️ ${L('Delete permanently','ہمیشہ کے لیے حذف کریں')}</h3><p>${L('This entry is removed from the records for good and cannot be undone. Stock and balances correct themselves. A line stays in the Activity Log.','یہ اندراج ریکارڈ سے مستقل ہٹ جائے گا۔ اسٹاک اور حساب خود درست ہو جائیں گے۔')}</p>${fld('reason','Reason · وجہ','text','','required')}${fld('password','Your password · اپنا پاس ورڈ','password','','required autocomplete=new-password')}<button class=btn style="background:linear-gradient(180deg,#ff8a7e,var(--bad));color:#fff;text-shadow:none">${L('Delete forever','حذف کریں')}</button> <button type=button class="btn alt" data-act=close>${L('Cancel','منسوخ')}</button></form>`};
H.delform=async(d,f)=>{await rpc('delete_entry',{p_table:f.dataset.t,p_id:+f.dataset.id,p_password:d.password,p_reason:d.reason});H.close();toast('✔ '+L('Deleted permanently','مستقل حذف'));route()};
H.editparty=async d=>{const p=(await sb.from('party_balance').select('*').eq('id',d.id).single()).data;const n=prompt('Name / نام',p.name);if(!n)return;const m=prompt('Mobile / موبائل',p.mobile||'');if(m===null)return;const{error}=await sb.from('parties').update({name:n,mobile:m||null}).eq('id',d.id);error?toast('⚠ '+error.message):route()};
H.archive=async d=>{if(!confirm('Remove this person from the lists? Only possible when the balance is zero. Old records are kept. / ہٹائیں؟'))return;await rpc('archive_party',{p_id:+d.id});toast('✔');route()};
H.addparty=async(d,f)=>{await ins('parties',{kind:f.dataset.kind,name:d.name,mobile:d.mobile||null});route()};
V.ledger=async(id,mode)=>{const p=(await sb.from('party_balance').select('*').eq('id',id).single()).data,c=p.kind==='customer';
 const[T,Y,LN]=(await Promise.all([sb.from(c?'sales':'purchases').select('*,products(name_en)').eq('party_id',id).eq('voided',false).order('id'),sb.from('payments').select('*').eq('party_id',id).eq('voided',false).order('id'),sb.from('loan_status').select('*').eq('party_id',id).eq('voided',false)])).map(r=>r.data||[]);
 const n=new Date(),start=mode==='today'?today():mode==='month'?iso(new Date(n.getFullYear(),n.getMonth(),1)):'0000-00-00';
 const rows=[...T.map(x=>({d:x.d,o:0,id:x.id,tb:c?'sales':'purchases',t:`${c?'Sale':'Purchase'} ${pad(c?'S-':'P-',x.id)}: ${esc(x.products.name_en)} ${fmt(x.qty)} × ${fmt(x.unit_price)} · ${esc(x.handled_by||'')}`,dr:+x.total,cr:0})),...Y.map(x=>({d:x.d,o:1,id:x.id,tb:'payments',t:`${c?'Received':'Paid'} (${x.method}) ${esc(x.note||'')} · ${esc(x.handled_by||'')}`,dr:0,cr:+x.amount}))].sort((a,b)=>a.d<b.d?-1:a.d>b.d?1:a.o-b.o||a.id-b.id);
 const open=sum(rows.filter(x=>x.d<start),x=>x.dr-x.cr),cur=rows.filter(x=>x.d>=start);let run=open;
 const PL=[];const R=cur.map(x=>{run=r2(run+x.dr-x.cr);PL.push([x.d,plain(x.t),x.dr?fmt(x.dr):'',x.cr?fmt(x.cr):'',fmt(run)]);return tr([x.d,x.t,x.dr?fmt(x.dr):'',x.cr?fmt(x.cr):'',fmt(run),`<button class="btn sm alt" data-act=del data-t=${x.tb} data-id=${x.id} title="Delete">✖</button>`])});
 if(start>'0000')R.unshift(tr(['',`<b>${L('Previous balance','پچھلا حساب')}</b>`,'','',`<b>${fmt(open)}</b>`,'']));
 const given=sum(LN.filter(x=>x.kind==='given'),x=>x.remaining),taken=sum(LN.filter(x=>x.kind==='taken'),x=>x.remaining),owes=r2((c?p.balance:-p.balance)+given-taken);
 const bill=sum(cur,x=>x.dr),paid=sum(cur,x=>x.cr),tab=(m,l)=>`<a class="btn sm ${(mode||'')===m?'':'alt'}" style="text-decoration:none;display:inline-block" href="#/ledger/${id}${m?'/'+m:''}">${l}</a>`;
 lastLedger={p,c,owes,given,taken,PL,open,start,mode};return`<h2>${esc(p.name)}</h2><p class=muted>${esc(p.mobile||'')} · <a href="#/${c?'customers':'suppliers'}">← ${L('Back','واپس')}</a></p>`
 +`<div class=card><b class="${owes?'neg':'pos'}" style="font-size:1.15rem">${owes>0?L('He owes you','اس نے آپ کو دینا ہے')+': Rs '+fmt(owes):owes<0?L('You owe him','آپ نے اسے دینا ہے')+': Rs '+fmt(-owes):L('Account clear','حساب صاف')}</b><br><span class=muted>${L('Goods + cash loans, all time','سامان اور نقد قرض، کل حساب')}</span></div>`
 +stats([[c?(p.balance<0?L('Advance he paid','اس کا ایڈوانس'):L('Goods balance he owes','سامان کا بقایا')):(p.balance<0?L('Advance you paid','آپ کا ایڈوانس'):L('Goods balance you owe','سامان کا بقایا')),Math.abs(p.balance)],[L('Cash loan given to him (left)','اسے دیا قرض (باقی)'),given],[L('Cash loan taken from him (left)','اس سے لیا قرض (باقی)'),taken]])
 +`<p>${tab('today',L('Today','آج'))} ${tab('month',L('This month','اس مہینے'))} ${tab('',L('All','تمام'))} <button class="btn sm alt" data-act=stmt>⬇ PDF</button> <button class="btn sm alt" data-act=stmtx>⬇ Excel</button></p>`
 +stats([[L('Bill in period','بل'),bill],[L('Paid in period','ادا شدہ'),paid],[L('Unpaid in period','بقایا'),r2(bill-paid)]])
 +`<form class=card data-act=ledgerpay data-id=${id} data-dir=${c?'in':'out'}><div class=form2>${fld('amount',c?'Receive payment · وصولی':'Pay supplier · ادائیگی','number','','min=0.01 step=any required')}${sel('method','Method',METHOD)}${byf()}${fld('date','Date','date',today(),'required')}</div><button class=btn>💾 ${L('Save payment','ادائیگی محفوظ کریں')}</button>${c&&p.balance>0?` <a class="btn alt" style="display:inline-block;text-decoration:none" target=_blank href="${wa(p.mobile,`Assalamu alaikum ${p.name}, your balance with Ansha Inam Plastic Industry is Rs ${fmt(p.balance)}. Please pay at your earliest convenience. Thank you.`)}">🔔 ${L('Remind on WhatsApp','واٹس ایپ یاد دہانی')}</a>`:''}</form>`
 +tbl(['Date','Details','Debit','Credit','Balance',''],R)};
H.ledgerpay=async(d,f)=>{await ins('payments',{d:d.date,party_id:+f.dataset.id,dir:f.dataset.dir,amount:+d.amount,method:d.method,note:'Payment',handled_by:d.by});localStorage.by=d.by;toast('✔');route()};
// ---------- Loans
const loans=k=>async()=>{const[Ls,LP,PB]=await Promise.all([all('loan_status'),all('loan_payments'),all('party_balance')]),g=k==='given',rows=Ls.filter(x=>x.kind===k).reverse();
 return`<h2>${g?L('Money Lent (Loan Given)','قرض دیا'):L('Money Borrowed (Loan Taken)','قرض لیا')}</h2><form class=card data-act=addloan data-kind=${k}><div class=form2>${fld('person',(g?'Borrower':'Lender')+' · نام (or pick below)','text','')}${sel('party','Link to customer/supplier (optional) · لنک',[['','— none —'],...PB.filter(x=>!x.archived).map(x=>[x.id,x.name+' ('+x.kind+')'])])}${byf()}${fld('mobile','Mobile · موبائل')}${fld('amount','Amount · رقم','number','','min=1 step=any required')}${fld('date','Date','date',today(),'required')}${fld('reason','Reason · وجہ')}${fld('due','Due date · واپسی تاریخ (optional)','date')}${sel('method','Method',METHOD)}</div><button class=btn>💾 ${L('Save','محفوظ')}</button></form>`
 +tbl(['Person','Date','Amount','Repaid','Remaining','Status','',''],rows.map(x=>tr([esc(x.person)+`<br><span class=muted>${esc(x.reason||'')}${x.due?' · due '+x.due:''}</span>`,x.d,fmt(x.amount),fmt(x.paid)+(LP.some(p=>p.loan_id===x.id)?`<br><span class=muted>${LP.filter(p=>p.loan_id===x.id).map(p=>p.d+': '+fmt(p.amount)+` <button class="btn sm alt" data-act=del data-t=loan_payments data-id=${p.id} title="Delete">✖</button>`).join('<br>')}</span>`:''),`<b>${fmt(x.remaining)}</b>`,`<span class="badge ${x.status}">${x.status}</span>`,x.remaining>0?`<button class="btn sm" data-act=repay data-id=${x.id} data-rem=${x.remaining}>${g?L('Receive repayment','وصولی'):L('Pay Loan','قرض واپس کریں')}</button>`:'',x.paid==0?`<button class="btn sm alt" data-act=del data-t=loans data-id=${x.id} title="Delete">✖</button>`:''])))};
V.given=loans('given');V.taken=loans('taken');
H.addloan=async(d,f)=>{const o=f.elements.party.selectedOptions[0],nm=d.person||(d.party?o.text.replace(/ \([a-z]+\)$/,''):'');if(!nm)return toast('Name required / نام ضروری');localStorage.by=d.by;await ins('loans',{kind:f.dataset.kind,person:nm,party_id:d.party?+d.party:null,mobile:d.mobile||null,amount:+d.amount,d:d.date,reason:d.reason||null,due:d.due||null,method:d.method,handled_by:d.by});route()};
H.repay=async d=>{const a=prompt(`Amount (remaining ${fmt(d.rem)}) / رقم`);if(!a)return;const m=prompt('cash or bank?','cash');await rpc('pay_loan',{p_loan:+d.id,p_amount:+a,p_method:m==='bank'?'bank':'cash',p_date:today()});toast('✔');route()};
// ---------- Expenses
V.expenses=async()=>{const E=await all('expenses'),C=/* HINT: edit this list to change the expense categories */['Electricity bill · بجلی','Rent · کرایہ','Labour · مزدوری','Transport · ٹرانسپورٹ','Packing · پیکنگ','Repair · مرمت','Other · دیگر'].map(x=>[x,x]);
 return`<h2>${L('Expenses','اخراجات')}</h2><form class=card data-act=addexp><div class=form2>${sel('category','Category',C)}${fld('amount','Amount · رقم','number','','min=1 step=any required')}${fld('date','Date','date',today(),'required')}${sel('method','Method',METHOD)}${fld('note','Details · تفصیل')}</div><button class=btn>💾 ${L('Save','محفوظ')}</button></form><p><b>${L('Total','کل')}: Rs ${fmt(sum(E,x=>x.amount))}</b></p>`+tbl(['Date','Category','Amount','Method','Details',''],E.slice().reverse().slice(0,200).map(x=>tr([x.d,esc(x.category),fmt(x.amount),x.method,esc(x.note),`<button class="btn sm alt" data-act=del data-t=expenses data-id=${x.id} title="Delete">✖</button>`])))};
H.addexp=async d=>{await ins('expenses',{d:d.date,category:d.category,amount:+d.amount,method:d.method,note:d.note||null});route()};
// ---------- Cash flow
V.cash=async()=>{const[Pay,E,LP,LN,B]=await Promise.all(['payments','expenses','loan_payments','loans','party_balance'].map(all)),k={};LN.forEach(l=>k[l.id]=l.kind);const d=today();
 const flow=(m,dt)=>{const f=x=>(!m||x.method===m)&&(!dt||x.d===dt);const i=sum(Pay.filter(x=>x.dir==='in'&&f(x)),x=>x.amount)+sum(LN.filter(x=>x.kind==='taken'&&f(x)),x=>x.amount)+sum(LP.filter(x=>k[x.loan_id]==='given'&&f(x)),x=>x.amount),o=sum(Pay.filter(x=>x.dir==='out'&&f(x)),x=>x.amount)+sum(E.filter(f),x=>x.amount)+sum(LN.filter(x=>x.kind==='given'&&f(x)),x=>x.amount)+sum(LP.filter(x=>k[x.loan_id]==='taken'&&f(x)),x=>x.amount);return{i:r2(i),o:r2(o),n:r2(i-o)}};
 const lg=sum(LN.filter(x=>x.kind==='given'),x=>x.amount)-sum(LP.filter(x=>k[x.loan_id]==='given'),x=>x.amount),lt=sum(LN.filter(x=>x.kind==='taken'),x=>x.amount)-sum(LP.filter(x=>k[x.loan_id]==='taken'),x=>x.amount);
 lastCash=[['Cash in hand','Rs '+fmt(flow('cash').n)],['Bank balance','Rs '+fmt(flow('bank').n)],['Received today','Rs '+fmt(flow(null,d).i)],['Paid today','Rs '+fmt(flow(null,d).o)],['Customers owe (total)','Rs '+fmt(sum(B.filter(x=>x.kind==='customer'&&x.balance>0),x=>x.balance))],['We owe suppliers (total)','Rs '+fmt(sum(B.filter(x=>x.kind==='supplier'&&x.balance>0),x=>x.balance))],['Loans to recover','Rs '+fmt(lg)],['Loans to repay','Rs '+fmt(lt)]];
 return`<h2>${L('Cash Flow & Closing','کیش فلو اور کلوزنگ')}</h2>`+stats([[L('Cash in hand','موجودہ نقد'),flow('cash').n],[L('Bank balance','بینک میں رقم'),flow('bank').n],[L('Received today','آج کی وصولیاں'),flow(null,d).i],[L('Paid today','آج کی ادائیگیاں'),flow(null,d).o],[L('Customers owe','کل بقایا وصولیاں'),sum(B.filter(x=>x.kind==='customer'&&x.balance>0),x=>x.balance)],[L('We owe suppliers','کل واجب الادا'),sum(B.filter(x=>x.kind==='supplier'&&x.balance>0),x=>x.balance)],[L('Loans to recover','دیا گیا قرض باقی'),lg],[L('Loans to repay','لیا گیا قرض باقی'),lt]])
 +`<button class=btn data-act=closing>⬇ ${L("Today's Cash Closing (Excel)",'آج کی کیش کلوزنگ')}</button> <button class="btn alt" data-act=closingpdf>⬇ PDF</button><form class=card style="margin-top:16px" data-act=opening><h3>${L('Opening balance','ابتدائی رقم')}</h3><div class=form2>${fld('amount','Amount','number','','min=1 step=any required')}${sel('method','Method',METHOD)}${fld('date','Date','date',today())}</div><button class="btn alt">＋</button></form>`};
H.opening=async d=>{await ins('payments',{d:d.date,dir:'in',amount:+d.amount,method:d.method,note:'Opening balance'});route()};
H.closing=()=>xls(today(),today(),`cash_closing_${today()}`);
// ---------- Reports
async function data(from,to){const[S,P,Pay,E,LP,LN,PR,B]=await Promise.all(['sales','purchases','payments','expenses','loan_payments','loans','products','party_balance'].map(all)),w=x=>x.d>=from&&x.d<=to,k={};LN.forEach(l=>k[l.id]=l.kind);
 const pn=Object.fromEntries(B.map(x=>[x.id,x.name])),pr=Object.fromEntries(PR.map(x=>[x.id,x.name_en]));
 const s=S.filter(w),p=P.filter(w),py=Pay.filter(w),e=E.filter(w),lp=LP.filter(w),ln=LN.filter(w);
 const gp=sum(s,x=>x.qty*(x.unit_price-x.unit_cost)),ex=sum(e,x=>x.amount);
 const days=[...new Set([...s,...p,...py,...e].map(x=>x.d))].sort();
 const daily=days.map(d=>{const ss=s.filter(x=>x.d===d),ee=sum(e.filter(x=>x.d===d),x=>x.amount),g=sum(ss,x=>x.qty*(x.unit_price-x.unit_cost));return{Date:d,Sales:sum(ss,x=>x.total),Purchases:sum(p.filter(x=>x.d===d),x=>x.total),Received:sum(py.filter(x=>x.d===d&&x.dir==='in'),x=>x.amount),'Paid out':sum(py.filter(x=>x.d===d&&x.dir==='out'),x=>x.amount),Expenses:ee,'Gross profit':g,'Net profit':r2(g-ee)}});
 const prod=PR.map(x=>{const a=s.filter(y=>y.product_id===x.id);return{Product:x.name_en,'Qty sold':sum(a,y=>y.qty),Revenue:sum(a,y=>y.total),Cost:sum(a,y=>y.qty*y.unit_cost),Profit:sum(a,y=>y.qty*(y.unit_price-y.unit_cost)),'Stock now':+x.stock}});
 const sum1={'Total sales':sum(s,x=>x.total),'Cost of goods sold':sum(s,x=>x.qty*x.unit_cost),'Gross profit':gp,Expenses:ex,'Net profit':r2(gp-ex),Purchases:sum(p,x=>x.total),Received:sum(py.filter(x=>x.dir==='in'),x=>x.amount),'Paid to suppliers':sum(py.filter(x=>x.dir==='out'),x=>x.amount),'Loans given':sum(ln.filter(x=>x.kind==='given'),x=>x.amount),'Loans recovered':sum(lp.filter(x=>k[x.loan_id]==='given'),x=>x.amount),'Loans taken':sum(ln.filter(x=>x.kind==='taken'),x=>x.amount),'Loans repaid':sum(lp.filter(x=>k[x.loan_id]==='taken'),x=>x.amount)};
 return{sum1,daily,prod,sheets:{Sales:s.map(x=>({No:pad('S-',x.id),Date:x.d,Customer:pn[x.party_id],Product:pr[x.product_id],Qty:x.qty,Price:x.unit_price,Total:x.total,Cost:x.unit_cost,By:x.handled_by||''})),Purchases:p.map(x=>({No:pad('P-',x.id),Date:x.d,Supplier:pn[x.party_id],Product:pr[x.product_id],Qty:x.qty,Price:x.unit_price,Total:x.total,By:x.handled_by||''})),Payments:py.map(x=>({Date:x.d,Party:pn[x.party_id]||'',Direction:x.dir,Amount:x.amount,Method:x.method,Ref:x.ref,Note:x.note,By:x.handled_by||''})),Expenses:e.map(x=>({Date:x.d,Category:x.category,Amount:x.amount,Method:x.method,Note:x.note})),'Loan repayments':lp.map(x=>({Date:x.d,Loan:x.loan_id,Type:k[x.loan_id],Amount:x.amount}))}}}
async function xls(from,to,name){const r=await data(from,to),wb=XLSX.utils.book_new(),add=(n,a)=>XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(a),n);add('Summary',[...Object.entries(r.sum1).map(([a,b])=>({Item:a,'Rs':b})),{Item:'Generated by',Rs:ME},{Item:'Generated at',Rs:stamp()}]);add('Daily',r.daily);add('Products',r.prod);for(const[n,a]of Object.entries(r.sheets))add(n,a);XLSX.writeFile(wb,name+'.xlsx')}
V.reports=async()=>{const r=await data(range.from,range.to);
 post=()=>{chart('c1','line',r.daily.map(x=>x.Date.slice(5)),[{label:'Sales',data:r.daily.map(x=>x.Sales)},{label:'Net profit',data:r.daily.map(x=>x['Net profit'])}]);chart('c2','bar',r.prod.map(x=>x.Product),[{label:'Revenue',data:r.prod.map(x=>x.Revenue)},{label:'Profit',data:r.prod.map(x=>x.Profit)}])};
 const n=r.sum1['Net profit'];
 return`<h2>${L('Reports & Profit/Loss','رپورٹس اور منافع/نقصان')}</h2>${tip('Choose dates (or Today / 7 days / Month / Year), then use Excel or PDF. Every report shows who made it and when.','تاریخیں چنیں (یا آج / ہفتہ / مہینہ / سال)، پھر Excel یا PDF دبائیں۔ ہر رپورٹ پر بنانے والے کا نام اور وقت ہوتا ہے۔')}<form class=card data-act=range><div class=form2>${fld('from','From','date',range.from)}${fld('to','To','date',range.to)}</div><button class=btn>${L('Show','دکھائیں')}</button> <button type=button class="btn alt" data-act=preset data-p=0>${L('Today','آج')}</button> <button type=button class="btn alt" data-act=preset data-p=6>${L('7 days','ہفتہ')}</button> <button type=button class="btn alt" data-act=preset data-p=m>${L('Month','مہینہ')}</button> <button type=button class="btn alt" data-act=preset data-p=y>${L('Year','سال')}</button> <button type=button class="btn alt" data-act=repxls>⬇ Excel</button> <button type=button class="btn alt" data-act=reppdf>⬇ PDF</button></form>`
 +stats(Object.entries(r.sum1).map(([a,b])=>[a,b,a==='Net profit'?(n>=0?'pos':'neg'):'']))+`<div class=card><canvas id=c1></canvas></div><div class=card><canvas id=c2></canvas></div><h3>${L('By product','مصنوعات کے لحاظ سے')}</h3>`+tbl(Object.keys(r.prod[0]||{Product:0}),r.prod.map(x=>tr(Object.values(x))))+`<h3>${L('By day','روزانہ')}</h3>`+tbl(Object.keys(r.daily[0]||{Date:0}),r.daily.map(x=>tr(Object.values(x))))};
H.range=d=>{range={from:d.from,to:d.to};route()};
H.preset=d=>{const n=new Date();range=d.p==='m'?monthRange():d.p==='y'?{from:n.getFullYear()+'-01-01',to:today()}:{from:iso(new Date(Date.now()-d.p*864e5)),to:today()};route()};
H.repxls=()=>xls(range.from,range.to,`report_${range.from}_to_${range.to}`);
