V.log=async()=>{const{data:A}=await sb.from('audit_log').select('*').order('id',{ascending:false}).limit(200);
 return`<h2>${L('Backup & Activity Log','بیک اپ اور ایکٹیویٹی لاگ')}</h2><div class=card><p>${L('Master Excel = every record since day one. Daily automatic database backup runs on GitHub (see README).','ماسٹر ایکسل میں پہلے دن سے تمام ریکارڈ۔')}</p><button class=btn data-act=master>⬇ ${L('Master Excel workbook','ماسٹر ایکسل')}</button> <button class="btn alt" data-act=json>⬇ JSON backup</button></div>`+tbl(['Time','User','Action','Table','Data'],A.map(x=>tr([new Date(x.at).toLocaleString(),esc(x.email),x.op,x.tbl,`<span class=muted>${esc(JSON.stringify(x.row).slice(0,110))}</span>`])))};
