H.master=async()=>{const wb=XLSX.utils.book_new();for(const t of TABLES)XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(await all(t,true)),t);XLSX.writeFile(wb,`master_${today()}.xlsx`)};
