V.settings=async()=>{const u=(await sb.auth.getUser()).data.user,PR=await all('products'),cn=localStorage.cols||'auto';
 return`<h2>${L('Settings','سیٹنگز')}</h2>${picCards(PR,cn)}<form class=card data-act=prof><h3>${L('Username','یوزر نیم')}</h3>${fld('username','Username',  'text',u.user_metadata?.username||'','required')}<button class=btn>💾</button></form><form class=card data-act=mail><h3>Email</h3>${fld('email','New email','email',u.email,'required')}<button class=btn>💾</button><p class=muted>${L('A confirmation link is sent to the new address.','نئے ای میل پر تصدیقی لنک بھیجا جائے گا۔')}</p></form><form class=card data-act=pass><h3>${L('Password','پاس ورڈ')}</h3>${fld('password','New password (min 8)','password','','minlength=8 required')}<button class=btn>💾</button></form><div class=card><h3>${L('Appearance','ظاہری شکل')}</h3><button class="btn alt" data-act=theme data-t=light>☀️ ${L('Light','روشن')}</button> <button class="btn alt" data-act=theme data-t=dark>🌙 ${L('Dark','تاریک')}</button></div><div class=card><h3>${L('Language','زبان')}</h3><button class="btn alt" data-act=lang data-l=en>English</button> <button class="btn alt" data-act=lang data-l=ur>اردو</button></div>`};
