async function route(){const[k,a,b]=(location.hash.slice(2)||'dash').split('/');drawNav(k);try{scrollTo(0,0)}catch(e){}post=null;const m=$('#main');m.innerHTML='<div class=sk></div><div class=sk style="width:70%"></div><div class=sk style="width:50%"></div>';
 try{m.innerHTML=await(V[k]||V.dash)(a,b);post&&post()}catch(e){m.innerHTML=`<p class=err>⚠ ${esc(e.message)}</p>`}}
async function enter(){const{data:{session}}=await sb.auth.getSession();if(!session)return show(false);const{data:ok}=await sb.rpc('is_allowed');if(!ok){await sb.auth.signOut();$('#loginErr').textContent='This account is not authorised.';return show(false)}const nm=session.user.user_metadata?.username||session.user.email;ME=session.user.user_metadata?.username?nm+' ('+session.user.email+')':nm;$('#who').textContent=nm;if(!localStorage.by)localStorage.by=/aizaz|اعجاز/i.test(nm)?'Aizaz Khan':'Inamullah';show(true);route()}
const show=v=>{$('#login').hidden=v;$('#app').hidden=!v};
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target;if(f.id==='loginForm'){const d=Object.fromEntries(new FormData(f)),{error}=await sb.auth.signInWithPassword(d);$('#loginErr').textContent=error?error.message:'';return error||enter()}
 const h=H[f.dataset.act];if(!h)return;const b=f.querySelector('button:not([type=button])');b&&(b.disabled=true);try{await h(Object.fromEntries(new FormData(f)),f)}catch(_){}b&&(b.disabled=false)});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b||b.tagName==='FORM')return;if(b.dataset.act==='logout'){e.preventDefault();await sb.auth.signOut();return enter()}const h=H[b.dataset.act];if(h)try{await h(b.dataset,b)}catch(_){}});
applyCols();document.querySelectorAll('.brand-logo').forEach(i=>i.src=LOGO);{const f=document.createElement('link');f.rel='icon';f.href=LOGO;document.head.appendChild(f)}
addEventListener('hashchange',()=>!$('#app').hidden&&route());
setTheme(curTheme());
enter();
